use crate::aap::caps::inference_llm::infer;

struct Node;

const SYSTEM: &str = "You classify an inbound customer support message. \
Reply with exactly one lowercase label on the first line, chosen from: \
billing_question, technical_support, account_change, general_inquiry, unknown. \
Do not add any other text.";

/// Map a model label to the closed intent set. Anything we do not recognise
/// collapses to `Unknown` — the enum has no "other" case, so adversarial text
/// cannot widen the intent set.
fn classify_intent(raw: &str) -> Intent {
    let label = raw.trim().lines().next().unwrap_or("").trim().to_ascii_lowercase();
    // Accept both hyphen and underscore spellings defensively.
    let normalized = label.replace('-', "_");
    match normalized.as_str() {
        "billing_question" => Intent::BillingQuestion,
        "technical_support" => Intent::TechnicalSupport,
        "account_change" => Intent::AccountChange,
        "general_inquiry" => Intent::GeneralInquiry,
        _ => Intent::Unknown,
    }
}

/// Truncate to at most 512 characters on a char boundary, satisfying
/// `ensures len(question) <= 512`.
fn bound_question(text: &str) -> String {
    const MAX: usize = 512;
    if text.chars().count() <= MAX {
        text.to_string()
    } else {
        text.chars().take(MAX).collect()
    }
}

impl Guest for Node {
    fn run(message: RawMessage) -> CustomerQuery {
        // The only authority this node holds: ask the model for a label.
        let raw = infer(SYSTEM, &message.text, "classify");
        let intent = classify_intent(&raw);

        // The bounded, still-adversarial free-text residual.
        let question = bound_question(&message.text);

        CustomerQuery {
            intent,
            entities: Vec::new(),
            question,
        }
    }
}

export!(Node);
```

The `ensures` both hold by construction: `intent` is a WIT `enum` with no open case (unrecognized labels become `Unknown`), and `question` is truncated to ≤512 characters. The only import is the granted `inference-llm`.

