use crate::aap::caps::http_client::fetch;
use crate::aap::caps::inference_llm::infer;
use crate::aap::caps::types::Intent;

struct Node;

const SYSTEM: &str = "You classify an inbound customer support message. \
Reply with exactly one lowercase label on the first line, chosen from: \
billing_question, technical_support, account_change, general_inquiry, unknown. \
Do not add any other text.";

const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";

/// Map a model label to the closed intent set. Anything unrecognised
/// collapses to `Unknown`.
fn classify_intent(raw: &str) -> Intent {
    let label = raw
        .trim()
        .lines()
        .next()
        .unwrap_or("")
        .trim()
        .to_ascii_lowercase();
    let normalized = label.replace('-', "_");
    match normalized.as_str() {
        "billing_question" => Intent::BillingQuestion,
        "technical_support" => Intent::TechnicalSupport,
        "account_change" => Intent::AccountChange,
        "general_inquiry" => Intent::GeneralInquiry,
        _ => Intent::Unknown,
    }
}

/// Truncate to at most 512 characters, satisfying `ensures len(question) <= 512`.
fn bound_question(text: &str) -> String {
    const MAX: usize = 512;
    text.chars().take(MAX).collect()
}

/// Percent-encode a string for use as a URL query value.
fn percent_encode(s: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(s.len() * 3);
    for &b in s.as_bytes() {
        if b.is_ascii_alphanumeric() || b == b'-' || b == b'_' || b == b'.' || b == b'~' {
            out.push(b as char);
        } else {
            out.push('%');
            out.push(HEX[(b >> 4) as usize] as char);
            out.push(HEX[(b & 0x0F) as usize] as char);
        }
    }
    out
}

impl Guest for Node {
    fn run(message: RawMessage) -> CustomerQuery {
        // Enrichment fetch, as approved. The result is deliberately unused so
        // the node's output does not change; a transport failure is ignored.
        let url = format!("{}{}", ENRICH_BASE, percent_encode(&message.text));
        let _ = fetch(&url);

        let raw = infer(SYSTEM, &message.text, "classify");
        let intent = classify_intent(&raw);
        let question = bound_question(&message.text);

        CustomerQuery {
            intent,
            entities: Vec::new(),
            question,
        }
    }
}

export!(Node);
